'use strict';
const AWARDS=[['mvp','MVP','Most Valuable Player','Jogador mais valioso'],['roy','ROY','Rookie of the Year','Estreante do ano'],['coy','COY','Coach of the Year','Técnico do ano'],['clutch','CPOY','Clutch Player of the Year','Decisivo nos momentos finais'],['sixth','6MOY','Sixth Man of the Year','Sexto homem do ano'],['mip','MIP','Most Improved Player','Jogador que mais evoluiu']];
let KEY='nba-awards-2026-27-v1';
const all=[...NBA_DATA.players,...NBA_COACHES];
const lookup=new Map(all.map(p=>[p.id,p]));
function defaults(){return{version:1,season:'2026-27',picks:Object.fromEntries(AWARDS.map(([id])=>[id,['','','']])),results:Object.fromEntries(AWARDS.map(([id])=>[id,['','','']])),points:Object.fromEntries(AWARDS.map(([id])=>[id,{exact:[10,5,3],wrong:0}]))};}
function validate(s){if(!s||s.version!==1||s.season!=='2026-27')throw Error('Backup incompatível com esta temporada.');for(const[id]of AWARDS){const allowed=new Set((id==='coy'?NBA_COACHES:NBA_DATA.players).map(p=>p.id));for(const field of ['picks','results']){const a=s[field]?.[id];if(!Array.isArray(a)||a.length!==3||a.some(v=>typeof v!=='string'||(v!==''&&!allowed.has(v)))||new Set(a.filter(Boolean)).size!==a.filter(Boolean).length)throw Error('Backup contém seleções inválidas.');}const p=s.points?.[id];if(!p||!Array.isArray(p.exact)||p.exact.length!==3||[...p.exact,p.wrong].some(v=>typeof v!=='number'||!Number.isFinite(v)||v<0||v>1000000))throw Error('Pontuação inválida no backup.');}return s;}
let state=defaults(),storageOK=true;try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved));}catch(e){storageOK=false;}
let view='palpites',active=null,dbKind='players';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#save-state').textContent='Salvo neste navegador';}catch(e){storageOK=false;$('#save-state').textContent='Falha ao salvar — exporte um backup';toast('Não foi possível salvar. Exporte um backup para preservar os dados.');}}
function awardScore(id){const p=state.picks[id],r=state.results[id],config=state.points[id];return p.reduce((sum,x,i)=>{if(!x)return sum;if(r[i]===x)return sum+config.exact[i];if(r.includes(x))return sum+config.wrong;return sum;},0);}
function totals(){return{picks:AWARDS.reduce((n,[id])=>n+state.picks[id].filter(Boolean).length,0),results:AWARDS.reduce((n,[id])=>n+state.results[id].filter(Boolean).length,0),score:AWARDS.reduce((n,[id])=>n+awardScore(id),0)};}
function maximum(id){const p=state.points[id];return p.exact.reduce((n,v)=>n+Math.max(v,p.wrong),0);}
function initials(name){return name.split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('');}
function trophyIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 21h8M12 17v4M7 4h10v7a5 5 0 0 1-10 0V4Z"/><path d="M7 6H4v2a4 4 0 0 0 4 4m9-6h3v2a4 4 0 0 1-4 4"/></svg>';}
function portrait(p,large=false){if(!p)return '<span class="empty-avatar">+</span>';return `<span class="avatar ${large?'large':''}"><span class="avatar-fallback">${esc(initials(p.name))}</span>${p.id.startsWith('coach-')?'':`<img src="https://cdn.nba.com/headshots/nba/latest/260x190/${p.id}.png" alt="" loading="lazy" class="player-photo">`}</span>`;}
function heading(title,desc,tag='TEMPORADA 2026/27'){const featured=view==='palpites';return `<div class="page-heading ${featured?'season-banner':''}"><div class="heading-copy"><span class="award-code">${featured?'NBA AWARDS · 2026 — 2027':'TEMPORADA 2026 — 2027'}</span><h1>${title}</h1><p>${desc}</p>${featured?'<div class="banner-tags"><span>6 PRÊMIOS</span><span>18 ESCOLHAS</span><span>SEU TOP 3</span></div>':''}</div>${featured?'<div class="banner-players" aria-label="JT Thor"><span class="season-watermark" aria-hidden="true">26/27</span><img src="assets/jt-thor.png" alt="JT Thor" class="banner-thor"><span class="banner-caption">NBA AWARDS</span></div>':`<span class="pill">${tag}</span>`}</div>`;}
function stats(){const t=totals();return `<div class="stats"><div class="stat"><span class="stat-icon">${trophyIcon()}</span><div><span>SEUS PALPITES</span><strong>${t.picks}<small> / 18 escolhas</small></strong></div><span class="stat-progress" style="--progress:${t.picks/18*100}%"></span></div><div class="stat"><span class="stat-icon blue">◎</span><div><span>PONTUAÇÃO TOTAL</span><strong>${t.score}<small> pontos</small></strong></div></div><div class="stat"><span class="stat-icon red">▤</span><div><span>RESULTADOS</span><strong>${t.results}<small> / 18 posições</small></strong></div></div></div>`;}
function rows(id,field){return state[field][id].map((value,i)=>{const p=lookup.get(value);return `<div class="rank-row ${i===0?'first-place':''}"><span class="rank rank-${i}">${i+1}<small>º</small></span><button class="pick ${p?'':'empty'}" data-pick="${id}" data-field="${field}" data-rank="${i}" aria-label="${field==='picks'?'Palpite':'Resultado'} ${i+1}º, ${AWARDS.find(a=>a[0]===id)[2]}${p?', '+esc(p.name):''}">${portrait(p,i===0)}<span class="pick-text">${i===0?'<span class="first-label">'+(field==='picks'?'SEU FAVORITO':'VENCEDOR')+'</span>':''}${p?`<b>${esc(p.name)}</b><small><span class="team-abbr">${esc(p.team)}</span> ${esc(p.teamName)}</small>`:'<b>Escolher '+(id==='coy'?'técnico':'jogador')+'</b><small>'+ (i===0?'Quem leva o prêmio?':'Defina o '+(i+1)+'º lugar')+'</small>'}</span><span class="plus">${p?'⌄':'+'}</span></button>${p?`<button class="clear" data-clear="${id}" data-field="${field}" data-rank="${i}" aria-label="Limpar ${i+1}º lugar">×</button>`:''}</div>`;}).join('');}
function card(a,index,field){const[id,code,title,translation]=a;const n=state[field][id].filter(Boolean).length;return `<article class="card award-card award-${id}"><div class="card-top"><div><span class="award-code">${code}</span><h2>${title}</h2><span class="translation">${translation}</span></div><span class="award-icon">${trophyIcon()}</span></div><div class="podium">${rows(id,field)}</div><div class="card-bottom"><span class="completion"><span class="completion-bars" aria-hidden="true">${[0,1,2].map(i=>`<i class="${i<n?'filled':''}"></i>`).join('')}</span>${n===3?'Top 3 completo':`${n}/3 escolhidos`}</span><span class="points-badge">${field==='results'?`<strong>${awardScore(id)} pts</strong>`:'Até '+maximum(id)+' pts'}</span></div>${field==='results'?`<div class="score-detail">Seu palpite: ${state.picks[id].map((v,i)=>`${i+1}º ${esc(lookup.get(v)?.name||'—')}`).join(' · ')}</div>`:''}</article>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#section-label').textContent={palpites:'MEUS PALPITES',pontuacao:'PONTUAÇÃO',resultados:'RESULTADOS',base:'BASE DE DADOS'}[view];
if(view==='palpites')$('#app').innerHTML=heading('FAÇA SEU TOP 3.','Escolha quem vai dominar a temporada. Monte o pódio de cada prêmio e acompanhe seus acertos.')+stats()+`<section class="grid" aria-label="Palpites">${AWARDS.map((a,i)=>card(a,i,'picks')).join('')}</section>`;
if(view==='resultados')$('#app').innerHTML=heading('Os resultados da temporada.','Preencha a classificação final de cada prêmio para conferir seus acertos.')+stats()+'<div class="notice">Os resultados são inseridos por você. Enquanto houver posições em aberto, a pontuação é parcial.</div>'+`<section class="grid" aria-label="Resultados">${AWARDS.map((a,i)=>card(a,i,'results')).join('')}</section>`;
if(view==='pontuacao')$('#app').innerHTML=heading('Defina o valor de cada acerto.','As regras são independentes para cada prêmio e recalculam sua pontuação automaticamente.')+'<div class="notice">Acerto na posição exata recebe os pontos de 1º, 2º ou 3º lugar. Um nome no top 3, mas em outra posição, recebe apenas os pontos de “posição diferente”. Os valores não se somam.</div>'+`<section class="grid">${AWARDS.map(([id,code,title,translation],i)=>`<article class="card"><div class="card-top"><div><span class="award-code">${code}</span><h2>${title}</h2><span class="translation">${translation}</span></div><span class="number">0${i+1}</span></div><div class="fields">${[0,1,2].map(n=>`<label>${n+1}º exato<input type="number" min="0" max="1000000" step="any" data-points="${id}" data-index="${n}" value="${state.points[id].exact[n]}" aria-label="Pontos por acerto no ${n+1}º lugar de ${title}"></label>`).join('')}</div><label class="wrong-field">No top 3, em posição diferente<input type="number" min="0" max="1000000" step="any" data-points="${id}" data-index="wrong" value="${state.points[id].wrong}" aria-label="Pontos em posição diferente de ${title}"></label></article>`).join('')}</section>`;
if(view==='base'){$('#app').innerHTML=heading('Jogadores e técnicos.','614 jogadores e os 30 técnicos. Base estática consultada em 08/10/2026.','30 TIMES')+`<div class="db-tools"><input id="db-search" placeholder="Buscar nome ou time…" aria-label="Buscar na base"><select id="db-kind" aria-label="Tipo"><option value="players">Jogadores (614)</option><option value="coaches">Técnicos (30)</option></select><select id="db-team" aria-label="Filtrar por time"><option value="">Todos os times</option>${[...new Map(NBA_DATA.players.map(p=>[p.team,p.teamName]))].sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('')}</select></div><p id="db-count" class="translation"></p><div class="table-wrap"><table><thead><tr><th>NOME</th><th>TIME</th><th>POSIÇÃO</th><th>ESTREANTE</th></tr></thead><tbody id="db-rows"></tbody></table></div>`;$('#db-kind').value=dbKind;renderDB();}
$('#app').insertAdjacentHTML('beforeend','<div class="mobile-tabs"><button id="mobile-export">Exportar backup</button><label>Importar backup<input id="mobile-import" type="file" accept="application/json"></label></div>');$('#mobile-export').onclick=exportBackup;$('#mobile-import').onchange=importBackup;
}
function normalized(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function renderDB(){dbKind=$('#db-kind').value;const term=normalized($('#db-search').value),team=$('#db-team').value;const list=(dbKind==='players'?NBA_DATA.players:NBA_COACHES).filter(p=>(!team||p.team===team)&&normalized(p.name+' '+p.teamName+' '+p.team).includes(term));$('#db-count').textContent=`${list.length} ${dbKind==='players'?'jogadores':'técnicos'} encontrados`;$('#db-rows').innerHTML=list.length?list.map(p=>`<tr><td><span class="db-player">${portrait(p)}<b>${esc(p.name)}</b></span></td><td>${esc(p.teamName)}</td><td>${esc(p.position||'—')}</td><td>${dbKind==='players'?(p.rookie?'<span class="badge">Estreante</span>':'—'):'—'}</td></tr>`).join(''):'<tr><td colspan="4">Nenhum nome encontrado.</td></tr>';}
function openPicker(id,field,rank){active={id,field,rank};$('#picker-context').textContent=`${AWARDS.find(a=>a[0]===id)[2].toUpperCase()} / ${rank+1}º LUGAR`;$('.dialog-top h2').textContent=id==='coy'?'Escolha um técnico':'Escolha um jogador';$('#search').value='';$('#rookie-only').checked=false;$('#rookie-label').hidden=id!=='roy';$('#rookie-label').style.display=id==='roy'?'block':'none';renderChoices();$('#picker').showModal();$('#search').focus();}
function renderChoices(){const{id,field,rank}=active;const term=normalized($('#search').value);const list=(id==='coy'?NBA_COACHES:NBA_DATA.players).filter(p=>(id!=='roy'||!$('#rookie-only').checked||p.rookie)&&normalized(p.name+' '+p.team+' '+p.teamName).includes(term));$('#choices').innerHTML=list.length?list.map(p=>{const used=state[field][id].some((x,i)=>i!==rank&&x===p.id);return `<button class="candidate" data-candidate="${p.id}" ${used?'disabled':''}>${portrait(p)}<span><b>${esc(p.name)}</b><small>${esc(p.teamName)}${used?' · Já selecionado':''}${p.rookie?' · Estreante':''}</small></span></button>`;}).join(''):'<p class="muted">Nenhum nome encontrado.</p>';}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nba-awards-2026-27-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado.');}
async function importBackup(event){const f=event.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('Arquivo muito grande.');const next=validate(JSON.parse(await f.text()));if(!confirm('Substituir os dados deste navegador pelo backup? No bolão, regras e resultados são definidos pelo organizador.'))return;state=window.bolaoImport?window.bolaoImport(next):next;save();render();toast('Backup importado.');}catch(e){toast(e.message||'Não foi possível importar o backup.');}finally{event.target.value='';}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;location.hash=view;render();}const pick=e.target.closest('[data-pick]');if(pick)openPicker(pick.dataset.pick,pick.dataset.field,Number(pick.dataset.rank));const clear=e.target.closest('[data-clear]');if(clear){state[clear.dataset.field][clear.dataset.clear][Number(clear.dataset.rank)]='';save();render();}const candidate=e.target.closest('[data-candidate]');if(candidate&&!candidate.disabled){state[active.field][active.id][active.rank]=candidate.dataset.candidate;save();$('#picker').close();render();}});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-points]')){const val=Number(t.value),id=t.dataset.points,key=t.dataset.index;if(t.value.trim()===''||!Number.isFinite(val)||val<0||val>1000000){toast('Use um número entre 0 e 1.000.000.');t.value=key==='wrong'?state.points[id].wrong:state.points[id].exact[Number(key)];return;}if(key==='wrong')state.points[id].wrong=val;else state.points[id].exact[Number(key)]=val;save();}if(t.id==='db-kind'||t.id==='db-team')renderDB();});
document.addEventListener('input',e=>{if(e.target.id==='db-search')renderDB();});$('#search').oninput=renderChoices;$('#rookie-only').onchange=renderChoices;$('#close-picker').onclick=()=>$('#picker').close();$('#export').onclick=exportBackup;$('#import').onchange=importBackup;window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['palpites','pontuacao','resultados','base'].includes(next)&&next!==view){view=next;render();}});if(['palpites','pontuacao','resultados','base'].includes(location.hash.slice(1)))view=location.hash.slice(1);render();if(!storageOK){$('#save-state').textContent='Dados anteriores indisponíveis';toast('Não foi possível carregar os dados salvos. Importe um backup se necessário.');}

document.addEventListener('error',e=>{if(e.target.matches?.('.player-photo'))e.target.remove();},true);
